#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include "model/arch_qwen.hpp"

void require(bool ok, const char* msg) { if (!ok) throw std::runtime_error(msg); }
int main(int argc, char** argv) {
    if (argc != 3) return 2;
    auto weights = gguf::read_gguf(argv[1]);
    std::ofstream out(argv[2], std::ios::binary);
    size_t vectors = 0;
    auto save = [&](const std::vector<float>& values) {
        require(values.size() == 257, "vocab");
        for (float x : values) require(std::isfinite(x), "nonfinite");
        out.write(reinterpret_cast<const char*>(values.data()), values.size() * sizeof(float));
        ++vectors;
    };
    for (int nt : {1, 4}) {
        infer::Model a(weights), b(weights);
        a.set_threads(nt); b.set_threads(nt);
        const int limit = a.context_length();
        require(limit == 67, "context fixture");
        auto reject = [&](auto fn, infer::Model& m) {
            int before = m.n_tokens(); bool thrown = false;
            try { fn(); } catch (const std::runtime_error&) { thrown = true; }
            require(thrown && m.n_tokens() == before, "rejection changed position");
        };
        reject([&] { a.prefill({}); }, a);
        for (int i = 0; i < limit; ++i) {
            save(a.step((i * 17 + 11) % 257));
            require(a.n_tokens() == i + 1, "step position");
        }
        reject([&] { a.step(0); }, a);
        reject([&] { a.prefill({1}); }, a);
        // Reuse the largest allocation after reset, including shorter histories.
        for (int ub : {1, 2, 3, 7, 16, 128}) {
            a.reset(); a.set_ubatch(ub);
            int pos = 0;
            for (int count : {1, 3, 5, 8, 17, 33}) {
                std::vector<uint32_t> ids;
                for (int j = 0; j < count; ++j) ids.push_back((pos++ * 13 + ub) % 257);
                if (count == 1) save(a.step(ids[0]));
                else save(a.prefill(ids));
                require(a.n_tokens() == pos, "prefill position");
            }
            require(pos == limit, "history length");
            reject([&] { a.step(1); }, a);
            a.reset(); require(a.n_tokens() == 0, "reset position");
            save(a.prefill({3, 4, 5})); save(a.step(6));
        }
        // Growth during mixed histories, rather than only after retained capacity.
        for (int ub : {2, 7, 128}) {
            infer::Model fresh(weights); fresh.set_threads(nt); fresh.set_ubatch(ub);
            int pos = 0;
            for (int count : {3, 1, 5, 1, 13, 1, 19, 1, 23}) {
                std::vector<uint32_t> ids;
                for (int j = 0; j < count; ++j) ids.push_back((pos++ * 23 + ub) % 257);
                save(count == 1 ? fresh.step(ids[0]) : fresh.prefill(ids));
            }
            require(pos == limit && fresh.n_tokens() == limit, "grown history length");
        }
        // Shared read-only weights with separate mutable model state.
        a.reset(); b.reset(); a.set_ubatch(128); b.set_ubatch(3);
        save(a.prefill({1, 2, 3, 4})); save(b.prefill({17, 19, 23}));
        a.reset(); save(a.step(7)); save(b.step(29));
        b.reset(); save(b.step(31)); save(a.step(11));
        a.reset();
        reject([&] { a.prefill(std::vector<uint32_t>(68, 1)); }, a);
        save(a.step(2));
    }
    require(bool(out), "output write");
    std::cout << "{\"vectors\":" << vectors << ",\"values\":" << vectors * 257 << "}\n";
}

