from pathlib import Path
import subprocess,json,os,hashlib,statistics,math
r=Path(os.environ['TEMP'])/'llmx-kv-head-major';out=r/'bench-nine';out.mkdir(exist_ok=False)
tokens=Path(os.environ['TEMP'])/'llmx-external-perf/eight-pairs/tokens.txt'
models={'Q8':Path.home()/'.cache/huggingface/hub/models--Qwen--Qwen3-0.6B-GGUF/snapshots/23749fefcc72300e3a2ad315e1317431b06b590a/Qwen3-0.6B-Q8_0.gguf','F32':Path(os.environ['TEMP'])/'Qwen3-0.6B-F32.gguf'}
arms={'control':r/'control-compare.exe','candidate':r/'candidate-compare.exe','mx':Path.cwd().parent/'llmx-ref/build/bin/Release/llmx-compare-threads.exe'}
paths=list(arms.values())+list(models.values())+[tokens]+list((r/'candidate').rglob('*.hpp'))+list((r/'control').rglob('*.hpp'))+[arms['mx'].parent/x for x in ['llama.dll','ggml.dll','ggml-base.dll','ggml-cpu.dll']]
hashes={}
for p in paths:
 with p.open('rb') as f: hashes[str(p)]=hashlib.file_digest(f,'sha256').hexdigest()
(out/'metadata.json').write_text(json.dumps(dict(hashes=hashes,threads=6,ubatch=128,prompt=215,decode=32,reference='5542318e748c154b634211def405ae95da3dfaa9',rounds=9,outer_warmup_rounds=1,process_warmup_sequences=1),indent=2))
rows=[]
for model,path in models.items():
 for round in range(-1,9):
  order=list(arms); shift=(round+1)%3; order=order[shift:]+order[:shift]
  for arm in order:
   p=subprocess.run([str(arms[arm]),str(path),str(tokens),'--threads','6'],capture_output=True)
   prefix=out/f'{model}-{round}-{arm}';prefix.with_suffix('.stdout').write_bytes(p.stdout);prefix.with_suffix('.stderr').write_bytes(p.stderr)
   p.check_returncode()
   values=[json.loads(x) for x in p.stdout.splitlines() if x]
   assert len(values)==2 and [x['run'] for x in values]==[0,1]
   for x in values:
    assert x['threads']==6 and x['pp_tokens']==215 and x['tg_tokens']==32
    assert all(math.isfinite(x[k]) and x[k]>0 for k in ['pp_ms','tg_ms']) and math.isfinite(x['logit_sum'])
   row=dict(model=model,round=round,arm=arm,**values[1]);rows.append(row)
   (out/'results.json').write_text(json.dumps(rows,indent=2));print(json.dumps(row),flush=True)
summary={}
for model in models:
 summary[model]={}
 for arm in arms:
  summary[model][arm]={}
  for phase in ['pp','tg']:
   rates=[x[phase+'_tokens']*1000/x[phase+'_ms'] for x in rows if x['model']==model and x['arm']==arm and x['round']>=0]
   summary[model][arm][phase]=dict(mean=statistics.mean(rates),minimum=min(rates),maximum=max(rates))
(out/'summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2),flush=True)

